/* MI BOWLING I13 LAB · Playwright WebKit and Chromium, HTTPS loopback only.
 * All keys/signed exports generated by Node test fixture, NEVER browser or app.
 */
'use strict';
const assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path'),
 os=require('node:os'),https=require('node:https'),cp=require('node:child_process');
const {webkit,chromium}=require('playwright');
const {A,B,PASS,fixture,clone}=require('./i13-witness-fixture.cjs');
const ROOT=path.resolve(__dirname,'..');
const TMP=fs.mkdtempSync(path.join(os.tmpdir(),'mi-bowling-i13-'));
let server;
const upload=(name,x)=>({name,mimeType:'application/json',
 buffer:Buffer.from(typeof x==='string'?x:JSON.stringify(x))});
async function start(){
 const key=path.join(TMP,'key.pem'),crt=path.join(TMP,'cert.pem');
 cp.execFileSync('openssl',['req','-x509','-nodes','-days','1','-newkey','rsa:2048',
  '-keyout',key,'-out',crt,'-subj','/CN=localhost',
  '-addext','subjectAltName=DNS:localhost,IP:127.0.0.1'],{stdio:'ignore'});
 server=https.createServer({key:fs.readFileSync(key),cert:fs.readFileSync(crt)},(req,res)=>{
  if(req.url==='/__blank'){
   res.writeHead(200,{'Content-Type':'text/html','Cache-Control':'no-store'});
   res.end('<!doctype html><title>I13 Fixture</title>');return;
  }
  const f=path.resolve(ROOT,decodeURIComponent(
   new URL(req.url,'https://127.0.0.1').pathname).replace(/^\/+/,''));
  if(!f.startsWith(ROOT+path.sep)||!fs.existsSync(f)||!fs.statSync(f).isFile()){
   res.writeHead(404);res.end('Not found');return;
  }
  res.writeHead(200,{'Content-Type':f.endsWith('.js')?'application/javascript':'text/html',
   'Cache-Control':'no-store','Referrer-Policy':'no-referrer'});
  res.end(fs.readFileSync(f));
 });
 await new Promise((ok,no)=>{server.once('error',no);server.listen(0,'127.0.0.1',ok)});
 return'https://127.0.0.1:'+server.address().port;
}
async function run(engine,base,label,fx){
 const browser=await engine.launch(label==='chromium'?{
  executablePath:cp.execFileSync('which',['google-chrome'],{encoding:'utf8'}).trim(),
  headless:true,args:['--no-sandbox']}:{headless:true});
 const ctx=await browser.newContext({ignoreHTTPSErrors:true,
  viewport:{width:label==='webkit'?390:1300,height:840},locale:'es-ES'});
 await ctx.route('**/*',r=>r.request().url().startsWith(base+'/')?r.continue():r.abort());
 try{
  const p=await ctx.newPage();
  await p.goto(base+'/__blank');
  await p.evaluate(()=>localStorage.setItem('__I13_SENTINEL__','must-survive'));
  await p.goto(base+'/lab/integracion-main-auth-i13.html');
  assert.equal(await p.locator('body').getAttribute('data-lab'),'I13-OFFLINE-READONLY');
  assert.equal(await p.locator('script[src*="app.js"]').count(),0);
  assert.equal(await p.locator('script[src*="encrypted-store"]').count(),0);
  const pkg={bundle:fx.bundle,snapshots:fx.snapshots};
  await p.locator('#i13-pass').fill(PASS);
  await p.locator('#i13-package').setInputFiles(upload('witness.mw13',pkg));
  await p.locator('#i13-policy').setInputFiles(upload('external.trust13',fx.policy));
  await p.locator('#i13-pin').setInputFiles(upload('external.pin13',fx.pin));
  await p.locator('#i13-verify').click();
  await p.waitForFunction(()=>document.querySelector('#i13-status')
   ?.textContent.includes('QUÓRUM VERIFICADO CON PIN EXTERNO'));
  await p.locator('#i13-current').setInputFiles(upload('old.mae11',fx.rawFiles[0]));
  await p.locator('#i13-compare').click();
  await p.waitForFunction(()=>document.querySelector('#i13-status')
   ?.textContent.includes('rollback-or-suppression-detected'));
  const changed=clone(fx.policy);changed.threshold=3;
  await p.locator('#i13-policy').setInputFiles(upload('replaced.trust13',changed));
  await p.locator('#i13-verify').click();
  await p.waitForFunction(()=>document.querySelector('#i13-status')
   ?.textContent.includes('I13 BLOQUEADO'));
  assert.match(await p.locator('#i13-status').textContent(),/SUSTITUCIÓN/);
  await p.locator('#i13-policy').setInputFiles(upload('external.trust13',fx.policy));
  const removed=clone(pkg);removed.snapshots[1].files.pop();
  await p.locator('#i13-package').setInputFiles(upload('missing.mw13',removed));
  await p.locator('#i13-verify').click();
  await p.waitForFunction(()=>document.querySelector('#i13-status')
   ?.textContent.includes('I13 BLOQUEADO'));
  await p.locator('#i13-package').setInputFiles(upload('witness.mw13',pkg));
  await p.locator('#i13-owner').selectOption(B);
  await p.locator('#i13-verify').click();
  await p.waitForFunction(()=>document.querySelector('#i13-status')
   ?.textContent.includes('I13 BLOQUEADO'));
  await p.locator('#i13-owner').selectOption(A);
  assert.equal(await p.evaluate(()=>localStorage.getItem('__I13_SENTINEL__')),'must-survive');
  assert.equal(await p.evaluate(()=>typeof indexedDB.databases==='function'?
   indexedDB.databases().then(x=>x.length):0),0);
  console.log('PASS I13 '+label+' · external pinned 2-of-3 quorum, signed continuity, rollback, replaced policy, lost exports, B isolation, no IDB/network/real keys');
 }finally{await ctx.close();await browser.close()}
}
(async()=>{
 const fx=await fixture(A,2),base=await start();
 try{await run(webkit,base,'webkit',fx);await run(chromium,base,'chromium',fx)}
 finally{await new Promise(done=>server.close(done));fs.rmSync(TMP,{recursive:true,force:true})}
})().catch(e=>{console.error(e);process.exitCode=1});
